mapper.select:
SELECT  FROM terms
WHERE terms_type = #{termsType}
ORDER BY effective_on DESC, id DESC

SELECT  FROM terms
WHERE terms_type = #{termsType} AND status = 'PUBLISHED' AND effective_on <= #{today}
ORDER BY effective_on DESC, id DESC LIMIT 1

mapper.update:
UPDATE faq SET category = #{category}, question = #{question}, answer = #{answer}, sort_order = #{sortOrder},
               exposed = #{exposed}, updated_by = #{by}, updated_at = now()
WHERE id = #{id}
